mapper.select:
select eotcd.*, eota.periods, eota.process_status, eota.loan_contract_code, eota.periods, eota.business_date from eg_out_table_contract_detail eotcd inner join eg_out_table_abs eota on eotcd.out_table_abs_id = eota.id where 1 = 1 and eotcd.del_flag = '0' and eota.del_flag = '0'
and eotcd.contract_code in
#{item}
and eota.process_status in
#{item}
and eota.loan_contract_code = #{param.loanContractCode}
and eotcd.org_id = #{param.orgId}
and eota.periods = #{param.periods}
and eotcd.contract_code = #{param.contractCode}

select ota.loan_contract_code, eotcd.contract_code, ota.periods, erp.plan_date, sum(erp.principal_amount) as principal_amount, sum(erp.interest_amount) as interest_amount, sum(erp.actual_repayment_principal_amount) as actual_repayment_principal_amount, sum(erp.actual_repayment_interes_amount) as actual_repayment_interes_amount from eg_out_table_abs ota inner join eg_out_table_contract_detail eotcd on ota.id = eotcd.out_table_abs_id left join eg_repayment_plan erp on eotcd.contract_code = erp.contract_code where 1 = 1 and ota.process_status in ('3', '4') and eotcd.del_flag = '0' and ota.del_flag = '0' and erp.del_flag ='0'
and eotcd.contract_code in
#{item}
and ota.loan_contract_code in
#{item}
and ota.periods in
#{item}
and to_char(erp.plan_date,'yyyy-MM-dd') >= to_char(to_date(#{param.startAccountDate},'yyyy-MM-dd'),'yyyy-MM-dd')
and to_char(erp.plan_date,'yyyy-MM-dd') <= to_char(to_date(#{param.endAccountDate},'yyyy-MM-dd'),'yyyy-MM-dd')
group by ota.loan_contract_code, eotcd.contract_code, ota.periods, erp.plan_date

