and eotcd.contract_code in
#{item}
and ota.loan_contract_code in
#{item}
and ota.periods in
#{item}
and to_char(erp.plan_date,'yyyy-MM-dd') >= to_char(to_date(#{param.startAccountDate},'yyyy-MM-dd'),'yyyy-MM-dd')
and to_char(erp.plan_date,'yyyy-MM-dd') <= to_char(to_date(#{param.endAccountDate},'yyyy-MM-dd'),'yyyy-MM-dd')
group by ota.loan_contract_code, eotcd.contract_code, ota.periods, erp.plan_date
